  function quintic(p0, v0, a0, p1, v1, a1, T, tau) {
    const c0 = p0, c1 = v0, c2 = 0.5 * a0;
    const dp = p1 - (p0 + v0 * T + 0.5 * a0 * T * T);
    const dv = v1 - (v0 + a0 * T);
    const da = a1 - a0;
    const T2 = T * T, T3 = T2 * T, T4 = T3 * T, T5 = T4 * T;
    const c3 = (10 * dp - 4 * T * dv + 0.5 * T2 * da) / T3;
    const c4 = (-15 * dp + 7 * T * dv - T2 * da) / T4;
    const c5 = (6 * dp - 3 * T * dv + 0.5 * T2 * da) / T5;
    const t2 = tau * tau, t3 = t2 * tau, t4 = t3 * tau, t5 = t4 * tau;
    return {
      p: c0 + c1 * tau + c2 * t2 + c3 * t3 + c4 * t4 + c5 * t5,
      v: c1 + 2 * c2 * tau + 3 * c3 * t2 + 4 * c4 * t3 + 5 * c5 * t4,
      a: 2 * c2 + 6 * c3 * tau + 12 * c4 * t2 + 20 * c5 * t3,
      j: 6 * c3 + 24 * c4 * tau + 60 * c5 * t2,
      s: 24 * c4 + 120 * c5 * tau,
    };
  }

  function smoothStep(u, width) {
    const x = clamp(u / width + 0.5, 0, 1);
    const x2 = x * x, x3 = x2 * x, x4 = x3 * x, x5 = x4 * x;
    return {
      val: 6 * x5 - 15 * x4 + 10 * x3,
      d1: (x > 0 && x < 1) ? (30 * x4 - 60 * x3 + 30 * x2) / width : 0,
      d2: (x > 0 && x < 1) ? (120 * x3 - 180 * x2 + 60 * x) / (width * width) : 0,
    };
  }

  function evalWind(params, t, lead, width) {
    let wx = params.baseWind.x, wz = params.baseWind.z;
    let dwx = 0, dwz = 0, d2wx = 0, d2wz = 0;
    const tl = t + lead;
    for (const g of params.gusts) {
      const s1 = smoothStep(tl - g.start, width);
      const s2 = smoothStep(tl - (g.start + g.duration), width);
      const w = s1.val - s2.val, dw = s1.d1 - s2.d1, d2w = s1.d2 - s2.d2;
      wx += g.x * w; wz += g.z * w;
      dwx += g.x * dw; dwz += g.z * dw;
      d2wx += g.x * d2w; d2wz += g.z * d2w;
    }
    return { wx, wz, dwx, dwz, d2wx, d2wz };
  }

  function testSeed(seed) {
    const params = trialParameters(seed);
    const state = initialState(params);
    const wps = [
      { t: 0.0, p: [state.pos.x, 0.07, state.pos.z], v: [0, 0, 0], a: [0, 0, 0] },
      { t: 2.2, p: [-1.15, 1.05, -0.85], v: [0.75, 0, 0], a: [0, 0, 0] },
      { t: 4.3, p: [0.15, 1.40, 0.25], v: [0.75, 0, 0], a: [0, 0, 0] },
      { t: 6.4, p: [1.35, 1.05, 1.05], v: [0.65, 0, 0], a: [0, 0, 0] },
      { t: 8.6, p: [2.05, 0.082, 1.65], v: [0, 0, 0], a: [0, 0, 0] },
    ];

    for (let step = 0; step < 1500 && !state.reason; step++) {
      const t = state.t;
      let rx, ry, rz;
      if (t >= wps[wps.length - 1].t) {
        const last = wps[wps.length - 1];
        rx = { p: last.p[0], v: 0, a: 0, j: 0, s: 0 };
        ry = { p: last.p[1], v: 0, a: 0, j: 0, s: 0 };
        rz = { p: last.p[2], v: 0, a: 0, j: 0, s: 0 };
      } else {
