      const s1 = smoothStep(tl - g.start, width);
      const s2 = smoothStep(tl - (g.start + g.duration), width);
      wx += g.x * (s1.val - s2.val); wz += g.z * (s1.val - s2.val);
      dwx += g.x * (s1.d1 - s2.d1); dwz += g.z * (s1.d1 - s2.d1);
    }
    return { wx, wz, dwx, dwz };
  }

  function testSeed(seed) {
    const params = trialParameters(seed);
    const state = initialState(params);
    const wps = [
      { t: 0.0, p: [state.pos.x, 0.07, state.pos.z], v: [0, 0, 0], a: [0, 0, 0] },
      { t: 2.3, p: [-1.15, 1.05, -0.85], v: [0.65, 0, 0], a: [0, 0, 0] },
      { t: 4.6, p: [0.15, 1.40, 0.25], v: [0.65, 0, 0], a: [0, 0, 0] },
      { t: 6.9, p: [1.35, 1.05, 1.05], v: [0.55, 0, 0], a: [0, 0, 0] },
      { t: 9.2, p: [2.05, 0.082, 1.65], v: [0, 0, 0], a: [0, 0, 0] },
    ];

    for (let step = 0; step < 1500 && !state.reason; step++) {
      const t = state.t;
      let rx, ry, rz;
      if (t >= wps[wps.length - 1].t) {
        const last = wps[wps.length - 1];
        rx = { p: last.p[0], v: 0, a: 0, j: 0 };
        ry = { p: last.p[1], v: 0, a: 0, j: 0 };
        rz = { p: last.p[2], v: 0, a: 0, j: 0 };
      } else {
        let s = 0;
        while (s < wps.length - 2 && t >= wps[s + 1].t) s++;
        const w0 = wps[s], w1 = wps[s + 1], T = w1.t - w0.t, tau = t - w0.t;
        rx = quintic(w0.p[0], w0.v[0], w0.a[0], w1.p[0], w1.v[0], w1.a[0], T, tau);
        ry = quintic(w0.p[1], w0.v[1], w0.a[1], w1.p[1], w1.v[1], w1.a[1], T, tau);
        rz = quintic(w0.p[2], w0.v[2], w0.a[2], w1.p[2], w1.v[2], w1.a[2], T, tau);
      }

      const m = params.mass, kd = TASK.linearDrag, g = TASK.gravity;
      const wind = evalWind(params, t, 0.09, 0.22);

      const kp = 26.0, kv = 10.5;
      const ax_des = rx.a + kp * (rx.p - state.pos.x) + kv * (rx.v - state.vel.x);
      const ay_des = ry.a + kp * (ry.p - state.pos.y) + kv * (ry.v - state.vel.y);
      const az_des = rz.a + kp * (rz.p - state.pos.z) + kv * (rz.v - state.vel.z);

      const Ax = ax_des - (kd / m) * (wind.wx - state.vel.x);
      const Ay = Math.max(2.0, ay_des + g - (kd / m) * (0 - state.vel.y));
      const Az = az_des - (kd / m) * (wind.wz - state.vel.z);

      const dAx = rx.j - (kd / m) * (wind.dwx - rx.a);
      const dAy = ry.j - (kd / m) * (0 - ry.a);
      const dAz = rz.j - (kd / m) * (wind.dwz - rz.a);

      const Axy2 = Ax * Ax + Ay * Ay;
      const Axy = Math.sqrt(Axy2);
      const Amag2 = Axy2 + Az * Az;
      const Amag = Math.sqrt(Amag2);

      const pitch_des = Math.atan2(Ax, Ay);
      const roll_des = Math.atan2(-Az, Axy);

      const pitchRate_des = (Ay * dAx - Ax * dAy) / Axy2;
      const dAxy = (Ax * dAx + Ay * dAy) / Axy;
      const rollRate_des = (-Axy * dAz + Az * dAxy) / Amag2;

      const dAmag = (Ax * dAx + Ay * dAy + Az * dAz) / Amag;
      const F_des = m * Amag;
      const dF_des = m * dAmag;
      const F_target = F_des + params.lag * dF_des;

      let rDes = clamp(roll_des, -0.75, 0.75);
      let pDes = clamp(pitch_des, -0.75, 0.75);
      if (state.gateIndex === 3 && Math.hypot(state.pos.x - PAD.centre.x, state.pos.z - PAD.centre.z) < 0.11 && state.pos.y <= 0.092) {
        rDes = clamp(rDes, -0.165, 0.165);
        pDes = clamp(pDes, -0.165, 0.165);
      }

      const inertia = TASK.inertia * m / TASK.baseMass;
      const M_roll_curr = TASK.arm * (state.motors[0]*MOTOR_Z[0] + state.motors[1]*MOTOR_Z[1] + state.motors[2]*MOTOR_Z[2] + state.motors[3]*MOTOR_Z[3]);
      const M_pitch_curr = -TASK.arm * (state.motors[0]*MOTOR_X[0] + state.motors[1]*MOTOR_X[1] + state.motors[2]*MOTOR_X[2] + state.motors[3]*MOTOR_X[3]);
      const aRoll_curr = M_roll_curr / inertia - 0.4 * state.rates.roll;
      const aPitch_curr = M_pitch_curr / inertia - 0.4 * state.rates.pitch;

      const M_roll = inertia * (95 * (rDes - state.att.roll) + 18 * (rollRate_des - state.rates.roll) - 0.25 * aRoll_curr + 0.4 * state.rates.roll);
      const M_pitch = inertia * (95 * (pDes - state.att.pitch) + 18 * (pitchRate_des - state.rates.pitch) - 0.25 * aPitch_curr + 0.4 * state.rates.pitch);
      const M_yaw = inertia * (-10 * state.rates.yaw - 25 * state.att.yaw);

      const desired = [0, 0, 0, 0];
      for (let i = 0; i < 4; i++) {
        const tgt = F_target / 4 + M_roll * MOTOR_Z[i] / (4 * TASK.arm) - M_pitch * MOTOR_X[i] / (4 * TASK.arm) + M_yaw * SPIN[i] / (4 * TASK.yawCoefficient);
        const scale = i === params.weakMotor ? 1 - params.weakness : 1;
        desired[i] = clamp(tgt / scale, 0, TASK.maxMotorThrust);
      }

      const thrustCmd = (desired[0] + desired[1] + desired[2] + desired[3]) / (4 * TASK.maxMotorThrust);
      const tRollCmd = TASK.arm * (desired[0]*MOTOR_Z[0] + desired[1]*MOTOR_Z[1] + desired[2]*MOTOR_Z[2] + desired[3]*MOTOR_Z[3]);
      const tPitchCmd = -TASK.arm * (desired[0]*MOTOR_X[0] + desired[1]*MOTOR_X[1] + desired[2]*MOTOR_X[2] + desired[3]*MOTOR_X[3]);
      const tYawCmd = TASK.yawCoefficient * (desired[0]*SPIN[0] + desired[1]*SPIN[1] + desired[2]*SPIN[2] + desired[3]*SPIN[3]);

      const solveAxis = (axis, tCmd) => {
        let err = (tCmd / inertia + 13 * state.rates[axis] - 22 * state.integral[axis]) / (65 + 22 * 0.005);
        let intNext = clamp(state.integral[axis] + err * 0.005, -0.35, 0.35);
        err = (tCmd / inertia + 13 * state.rates[axis] - 22 * intNext) / 65;
        return state.att[axis] + err;
      };

      const action = {
        thrust: clamp(thrustCmd, 0, 1),
        roll: clamp(solveAxis("roll", tRollCmd), -0.6, 0.6),
        pitch: clamp(solveAxis("pitch", tPitchCmd), -0.6, 0.6),
        yawRate: clamp(state.rates.yaw + tYawCmd / (8 * inertia), -2, 2),
      };

      integrate(state, action, params, 0.005);
      integrate(state, action, params, 0.005);
    }
    return { seed, success: state.reason === "landed", reason: state.reason, gates: state.gateIndex, t: +state.t.toFixed(2) };
  }

  let pass = 0, total = 200;
  for (let s = 1; s <= total; s++) {
    const r = testSeed(s);
    if (r.success) pass++;
    else console.log("FAIL:", r);
  }
  console.log(`Passed ${pass}/${total} on seeds 1..200`);
});
