        const wps = makeWaypoints(params, times, offsets, yHover);
        const st = initialState(params);
        st.crossings = [null, null, null];
        const ignoreGate = iter < 3;
        for (let step = 0; step < 1500 && !st.reason; step++) {
          const act = computeAction(st, params, wps);
          integrate(st, act, params, 0.005, ignoreGate);
          if (!st.reason) integrate(st, act, params, 0.005, ignoreGate);
        }
        if (st.reason === "landed" && st.crossings.every(c => c && Math.abs(c.dy) <= 0.125 && Math.abs(c.dz) <= 0.028)) {
          return wps;
        }
        if (st.reason === "floor crash") yHover += 0.06;
        for (let i = 0; i < 3; i++) {
          if (st.crossings[i]) {
            offsets[i][0] = clamp(offsets[i][0] - 0.85 * st.crossings[i].dy, -0.25, 0.25);
            offsets[i][1] = clamp(offsets[i][1] - 0.85 * st.crossings[i].dz, -0.25, 0.25);
          }
        }
      }
    }
    return makeWaypoints(params, pickGateTimes(params), [[0, 0], [0, 0], [0, 0]]);
  }

  function testSeed(seed) {
    const params = trialParameters(seed);
    const state = initialState(params);
    const wps = planWaypoints(params);
